import{_ as e,o as i,c as o,a2 as a}from"./chunks/framework.vLhlLNVn.js";const q=JSON.parse('{"title":"Getting Started in 5 minutes","description":"","frontmatter":{},"headers":[],"relativePath":"quick-start.md","filePath":"quick-start.md"}'),n={name:"quick-start.md"};function r(u,t,l,s,d,h){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="getting-started-in-5-minutes" tabindex="-1">Getting Started in 5 minutes <a class="header-anchor" href="#getting-started-in-5-minutes" aria-label="Permalink to &quot;Getting Started in 5 minutes&quot;">​</a></h1><p>We are using Azure AD because it is the most popular IdP used but the steps are similar to all IdPs. This guide assumes you&#39;ve installed the plugin and are using Craft CMS Pro, which is required.</p><h2 id="configure-my-provider-craft-as-an-sp" tabindex="-1">Configure &quot;My Provider&quot;, Craft as an SP <a class="header-anchor" href="#configure-my-provider-craft-as-an-sp" aria-label="Permalink to &quot;Configure &quot;My Provider&quot;, Craft as an SP&quot;">​</a></h2><p>First configure Craft as an SP. Open the plugin admin and goto &quot;My Provider&quot; in the side menu.</p><ol><li>Label the SP as needed. Adding environment here is helpful.</li><li>Click the &quot;Generate key pair&quot;</li></ol><h2 id="configure-the-idp-azure-ad-application" tabindex="-1">Configure the IdP - Azure AD Application <a class="header-anchor" href="#configure-the-idp-azure-ad-application" aria-label="Permalink to &quot;Configure the IdP - Azure AD Application&quot;">​</a></h2><p>Configuring the IdP varies. Here&#39;s how to configure Azure AD</p><ol><li>Sign-in to Azure AD and navigate to the Active Directory area.</li><li>On the Side menu, goto &quot;Enterprise Applications&quot;, then &quot;+ Create your own application&quot;, at the top left, name the application and click next.</li><li>Then click &quot;Single Sign-on&quot;, then &quot;SAML&quot;, where you&#39;ll land on &quot;Set up Single Sign-on with SAML&quot;.</li><li>Under &quot;Basic SAML Configuration&quot; <ol><li>set the Entity ID to Craft&#39;s &quot;My Provider&quot; Entity ID.</li><li>Reply URL can be found in the &quot;My Provider&quot; page under the &quot;Metadata&quot; tab (under &quot;Bindings&quot;) and labeled &quot;Assertion Consumer Service&quot;.</li><li>Set SLO there as well if desired</li><li>Save</li></ol></li><li>Under &quot;SAML Signing Certificate&quot; download &quot;Federation Metadata XML&quot;</li></ol><h2 id="configure-the-idp-in-craft" tabindex="-1">Configure the IdP in Craft <a class="header-anchor" href="#configure-the-idp-in-craft" aria-label="Permalink to &quot;Configure the IdP in Craft&quot;">​</a></h2><ol><li>Back in the Craft control panel, goto &quot;Provider List&quot; in the SAML SP Plugin side menu</li><li>Click &quot;+ Add Identity Provider&quot; to create the IdP</li><li>Configure require fields <ol><li>Add a human readable label</li><li>On the &quot;Metadata&quot; tab, paste the Federation Metadata XML downloaded from Azure AD</li><li>On the &quot;Configure&quot; tab, click &quot;+ Add a new mapping&quot; and set all mapping <ol><li>Set &quot;Attribute Name&quot; to &quot;<a href="http://schemas.xmlsoap.org/ws/2005/05/identity/claims/givenname" target="_blank" rel="noreferrer">http://schemas.xmlsoap.org/ws/2005/05/identity/claims/givenname</a>&quot; and &quot;Craft User Property&quot; to &quot;First Name&quot;</li><li>Set &quot;Attribute Name&quot; to &quot;<a href="http://schemas.xmlsoap.org/ws/2005/05/identity/claims/surname" target="_blank" rel="noreferrer">http://schemas.xmlsoap.org/ws/2005/05/identity/claims/surname</a>&quot; and &quot;Craft User Property&quot; to &quot;Last Name&quot;</li><li>Set &quot;Attribute Name&quot; to &quot;<a href="http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress" target="_blank" rel="noreferrer">http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress</a>&quot; and &quot;Craft User Property&quot; to &quot;Email&quot;. NOTE: Email is required.</li></ol></li></ol></li></ol><h2 id="configure-login-path" tabindex="-1">Configure Login Path <a class="header-anchor" href="#configure-login-path" aria-label="Permalink to &quot;Configure Login Path&quot;">​</a></h2><p>Within the <code>config/general.php</code>, you can set the <code>loginPath</code> to the value (&quot;Login Path&quot;) set in the IdP (within the Craft SAML SP Plugin control panel), under the &quot;Configure&quot; tab.</p><h2 id="other-plugin-configurations-and-recommendations" tabindex="-1">Other Plugin Configurations and Recommendations <a class="header-anchor" href="#other-plugin-configurations-and-recommendations" aria-label="Permalink to &quot;Other Plugin Configurations and Recommendations&quot;">​</a></h2><p>Create a <code>config/saml-sp.php</code> to add some of the following configurations:</p><ul><li><code>requireResponseToBeSigned</code> - By default, Azure AD doesn&#39;t sign the response. Set this value to <code>false</code>. This will error on login if the config isn&#39;t set to false and the signature isn&#39;t found.</li><li><code>entityId</code> - We recommend setting this to an environmental variable which matches the Entity ID of &quot;My Provider&quot; you created.</li></ul>',15)])])}const g=e(n,[["render",r]]);export{q as __pageData,g as default};
